#pragma once
#include "PluginProcessor.h"
#include <juce_gui_extra/juce_gui_extra.h>
class DrumPatternEditor final:public juce::Component,private juce::Timer {
public:
    explicit DrumPatternEditor(DrumAudioProcessor& p):processor(p){
        addAndMakeVisible(patterns);patterns.setComponentID("pattern-selector");patterns.onChange=[this]{if(refreshing)return;processor.getPatterns().stop();auto s=processor.getLibrary().snapshot();auto* kit=drum::activeKit(s);int index=patterns.getSelectedId()-1;if(kit && index>=0 && index<(int)kit->patterns.size())selected=kit->patterns[(size_t)index].id;refresh();};
        button(add,"+ Pattern",[this]{auto state=processor.getLibrary().snapshot();auto result=processor.getLibrary().addPattern(state.activeKit);if(result.ok)selected=result.id;message=result.ok?"Pattern created.":result.message;refresh();});
        button(remove,"Remove",[this]{juce::Component::SafePointer<DrumPatternEditor> safe(this);juce::AlertWindow::showAsync(juce::MessageBoxOptions().withTitle("Remove pattern?").withMessage("This removes the selected pattern from the kit.").withButton("Remove").withButton("Cancel").withAssociatedComponent(this),[safe](int result){if(safe && result==1){auto state=safe->processor.getLibrary().snapshot();safe->processor.getPatterns().stop();safe->processor.getLibrary().removePattern(state.activeKit,safe->selected);safe->refresh();}});});
        button(play,"Play pattern",[this]{if(processor.getPatterns().isRunning())processor.getPatterns().stop();else processor.getPatterns().start(selected);});
        button(exportButton,"Export MIDI...",[this]{chooseExport();});
        button(back,"Back to kit",[this]{processor.getPatterns().stop();setVisible(false);});
        addAndMakeVisible(drag);drag.setButtonText("Drag MIDI");drag.setTooltip("Drag this pattern to a DAW MIDI track or Explorer.");drag.begin=[this]{auto file=drum::PortableFiles::root().getChildFile("MIDI").getChildFile(juce::File::createLegalFileName(current.name)+"-"+juce::Uuid().toString()+".mid");auto result=writeMidi(file);if(result.ok){juce::StringArray files;files.add(file.getFullPathName());if(!juce::DragAndDropContainer::performExternalDragDropOfFiles(files,false,&drag))message="Drag could not start. Use Export MIDI instead.";}repaint();};
        addAndMakeVisible(name);name.setComponentID("pattern-name");name.onReturnKey=[this]{rename();};name.onFocusLost=[this]{rename();};
        addAndMakeVisible(length);length.addItem("1 bar / 16 steps",16);length.addItem("2 bars / 32 steps",32);length.addItem("4 bars / 64 steps",64);length.onChange=[this]{if(refreshing || current.id.isEmpty())return;auto edit=current;edit.steps=length.getSelectedId();std::erase_if(edit.hits,[&](const auto& hit){return hit.step>=edit.steps;});save(edit);};
        addAndMakeVisible(viewport);viewport.setViewedComponent(&grid,false);viewport.setScrollBarsShown(true,true);grid.changed=[this](int row,int step,int velocity){if(row<0 || row>=(int)grid.instruments.size() || current.id.isEmpty())return;auto edit=current;auto id=grid.instruments[(size_t)row].id;std::erase_if(edit.hits,[&](const auto& hit){return hit.instrumentId==id && hit.step==step;});if(velocity>0)edit.hits.push_back({id,step,velocity});save(edit);};
        refresh();startTimerHz(25);
    }
    ~DrumPatternEditor() override{stopTimer();processor.getPatterns().stop();viewport.setViewedComponent(nullptr,false);}
    void open(){auto state=processor.getLibrary().snapshot();if(auto* kit=drum::activeKit(state);kit && kit->patterns.empty()){auto result=processor.getLibrary().addPattern(state.activeKit);selected=result.id;}refresh();setVisible(true);toFront(false);}
    void paint(juce::Graphics& g) override{g.fillAll(juce::Colour(0xff101722));g.setColour(juce::Colour(0xff5dd8c0));g.setFont(22);g.drawText("PATTERNS",18,8,200,30,juce::Justification::centredLeft);g.setColour(juce::Colours::lightgrey);g.setFont(13);g.drawText("Click steps to toggle. Shift-drag vertically for velocity. Sixteenth notes, 4/4.",18,92,getWidth()-36,24,juce::Justification::centredLeft);g.drawText(message,18,getHeight()-30,getWidth()-36,24,juce::Justification::centredLeft);}
    void resized() override{back.setBounds(getWidth()-140,10,122,30);patterns.setBounds(18,49,160,32);add.setBounds(184,49,100,32);remove.setBounds(290,49,80,32);name.setBounds(380,49,160,32);length.setBounds(550,49,155,32);play.setBounds(18,121,120,32);drag.setBounds(148,121,120,32);exportButton.setBounds(278,121,130,32);viewport.setBounds(18,163,getWidth()-36,getHeight()-202);grid.setSize(juce::jmax(viewport.getWidth()-16,Grid::labelWidth+current.steps*Grid::cellWidth+8),juce::jmax(viewport.getHeight()-16,32+(int)grid.instruments.size()*Grid::rowHeight));}
private:
    struct DragButton:juce::TextButton{std::function<void()> begin;bool started=false;void mouseDown(const juce::MouseEvent& e) override{started=false;juce::TextButton::mouseDown(e);}void mouseDrag(const juce::MouseEvent& e) override{juce::TextButton::mouseDrag(e);if(!started && e.getDistanceFromDragStart()>5){started=true;if(begin)begin();}}};
    struct Grid:juce::Component{
        static constexpr int labelWidth=190,cellWidth=28,rowHeight=34;
        std::vector<drum::Instrument> instruments;drum::Pattern pattern;std::array<std::array<juce::uint8,64>,88> velocities{};
        void rebuild(){for(auto& row:velocities)row.fill(0);for(int row=0;row<(int)instruments.size();++row)for(const auto& hit:pattern.hits)if(hit.instrumentId==instruments[(size_t)row].id)velocities[(size_t)row][(size_t)hit.step]=(juce::uint8)hit.velocity;}int playhead=-1,dragRow=-1,dragStep=-1,startVelocity=100;std::function<void(int,int,int)> changed;
        int velocity(int row,int step)const{return velocities[(size_t)row][(size_t)step];}
        void paint(juce::Graphics& g) override{
            g.fillAll(juce::Colour(0xff18232f));g.setFont(12);g.setColour(juce::Colours::lightgrey);g.drawText("Instrument / key",8,0,labelWidth-10,30,juce::Justification::centredLeft);
            for(int step=0;step<pattern.steps;++step){g.setColour(juce::Colours::lightgrey);g.drawText(juce::String(step/16+1)+"."+juce::String(step%16/4+1),labelWidth+step*cellWidth,0,cellWidth,30,juce::Justification::centred);}
            for(int row=0;row<(int)instruments.size();++row){const auto& instrument=instruments[(size_t)row];int y=32+row*rowHeight;g.setColour(juce::Colours::lightgrey);g.drawText(instrument.name+" / "+drum::noteName(instrument.note),8,y,labelWidth-14,rowHeight,juce::Justification::centredLeft);
                for(int step=0;step<pattern.steps;++step){auto rect=juce::Rectangle<float>((float)(labelWidth+step*cellWidth+2),(float)y+3,cellWidth-4,rowHeight-6);int v=velocity(row,step);g.setColour(v?juce::Colour(0xff5dd8c0).withAlpha(.3f+.7f*v/127.0f):juce::Colour(step/4%2?0xff2d3b4c:0xff243142));g.fillRoundedRectangle(rect,3);if(v){g.setColour(juce::Colour(0xff101722));g.drawText(juce::String(v),rect.toNearestInt(),juce::Justification::centred);}if(step==playhead){g.setColour(juce::Colours::orange);g.drawRoundedRectangle(rect,3,2);}}
            }
            if(instruments.empty()){g.setColour(juce::Colours::lightgrey);g.drawText("Add instruments from Libraries to start a pattern.",12,42,500,30,juce::Justification::centredLeft);}
        }
        void mouseDown(const juce::MouseEvent& e) override{dragRow=(e.y-32)/rowHeight;dragStep=(e.x-labelWidth)/cellWidth;if(e.y<32 || e.x<labelWidth || dragRow<0 || dragRow>=(int)instruments.size() || dragStep<0 || dragStep>=pattern.steps){dragRow=-1;return;}int v=velocity(dragRow,dragStep);startVelocity=v?v:100;if(e.mods.isShiftDown()){if(!v)changed(dragRow,dragStep,startVelocity);}else changed(dragRow,dragStep,v?0:100);}
        void mouseDrag(const juce::MouseEvent& e) override{if(e.mods.isShiftDown() && dragRow>=0)changed(dragRow,dragStep,juce::jlimit(1,127,startVelocity-e.getDistanceFromDragStartY()));}
    };
    void button(juce::TextButton& b,const juce::String& text,std::function<void()> action){addAndMakeVisible(b);b.setButtonText(text);b.onClick=std::move(action);}
    void rename(){if(refreshing || current.id.isEmpty())return;auto edit=current;edit.name=name.getText().trim();save(edit);}
    void save(const drum::Pattern& p){auto state=processor.getLibrary().snapshot();auto result=processor.getLibrary().setPattern(state.activeKit,p);message=result.ok?"Pattern saved with this kit. Export again after changing the kit's key order.":result.message;refresh();}
    void refresh(){juce::ScopedValueSetter<bool> guard(refreshing,true);auto state=processor.getLibrary().snapshot();revision=state.revision;auto* kit=drum::activeKit(state);current={};grid.instruments.clear();patterns.clear(juce::dontSendNotification);if(kit){for(const auto& group:kit->groups)for(const auto& i:group.instruments)grid.instruments.push_back(i);int n=1;for(const auto& p:kit->patterns){patterns.addItem(p.name,n++);if(p.id==selected)current=p;}if(current.id.isEmpty() && !kit->patterns.empty()){current=kit->patterns.front();selected=current.id;}n=1;for(const auto& p:kit->patterns){if(p.id==selected)patterns.setSelectedId(n,juce::dontSendNotification);++n;}add.setEnabled(kit->patterns.size()<16);}grid.pattern=current;grid.rebuild();name.setText(current.name,false);length.setSelectedId(current.steps,juce::dontSendNotification);for(auto* c:std::initializer_list<juce::Component*>{&name,&length,&play,&remove,&drag,&exportButton})c->setEnabled(current.id.isNotEmpty());resized();grid.repaint();repaint();}
    drum::Result writeMidi(const juce::File& file){auto state=processor.getLibrary().snapshot();auto* kit=drum::activeKit(state);const drum::Pattern* pattern=nullptr;if(kit)for(const auto& p:kit->patterns)if(p.id==selected)pattern=&p;auto result=pattern?drum::PatternPlayer::exportMidi(*kit,*pattern,processor.getSampleEngine().auditionTempo(),file):drum::Result::fail("Select a pattern first.");message=result.ok?"MIDI exported. Existing DAW clips are unchanged.":result.message;repaint();return result;}
    void chooseExport(){chooser=std::make_unique<juce::FileChooser>("Export MIDI pattern",drum::PortableFiles::root().getChildFile("MIDI").getChildFile(juce::File::createLegalFileName(current.name)+".mid"),"*.mid");juce::Component::SafePointer<DrumPatternEditor> safe(this);chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[safe](const juce::FileChooser& dialog){if(safe && dialog.getResult()!=juce::File())safe->writeMidi(dialog.getResult());});}
    void timerCallback() override{if(!isVisible())return;auto revisionNow=processor.getLibrary().currentRevision();if(revisionNow!=revision)refresh();play.setButtonText(processor.getPatterns().isRunning()?"Stop pattern":"Play pattern");auto step=processor.getPatterns().playStep();if(step!=grid.playhead){grid.playhead=step;grid.repaint();}}
    DrumAudioProcessor& processor;juce::ComboBox patterns,length;juce::TextButton add,remove,play,exportButton,back;DragButton drag;juce::TextEditor name;juce::Viewport viewport;Grid grid;juce::String selected,message="Patterns follow instrument identities. Exported MIDI uses the current keyboard assignments.";drum::Pattern current;uint64_t revision=0;bool refreshing=false;std::unique_ptr<juce::FileChooser> chooser;
};
